      "content": "{\n  \"name\": \"dsh-lorebookmd\",\n  \"version\": \"1.0.0\",\n  \"description\": \"DSH lorebook-driven fiction writer plugin: import Tavern/SillyTavern character cards & world books, save local Markdown lore documents, and generate novel prose with the world settings as reference.\",\n  \"keywords\": [\n    \"dsh\",\n    \"deepseek-harness\",\n    \"plugin\",\n    \"lorebook\",\n    \"world-info\",\n    \"sillytavern\",\n    \"tavern\",\n    \"novel\",\n    \"fiction\"\n  ],\n  \"license\": \"MIT\",\n  \"type\": \"module\",\n  \"main\": \"lib/index.js\",\n  \"exports\": {\n    \".\": \"./lib/index.js\",\n    \"./client\": \"./lib/client.js\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"files\": [\n    \"lib\",\n    \"cordis.patch.yml\"\n  ],\n  \"engines\": {\n    \"node\": \">=22.18\"\n  },\n  \"scripts\": {\n    \"bundle\": \"node ./.dsh-tools/tsdown/run.mjs\",\n    \"typecheck\": \"node node_modules/typescript/bin/tsc --noEmit\",\n    \"test\": \"node --test tests/\"\n  },\n  \"dsh\": {\n    \"client\": {\n      \"inject\": [\n        \"slots\"\n      ],\n      \"platform\": \"web\"\n    },\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    }\n  }\n}\n"
